// Some portions generated by Codex
package org.eclipse.rdf4j.common.iteration;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class CancellationSignalTest {

	@Test
	void noneIsImmutable() {
		assertFalse(CancellationSignal.NONE.isCancelled());

		CancellationSignal.NONE.cancel();

		assertFalse(CancellationSignal.NONE.isCancelled());
	}

	@Test
	void childrenObserveParentCancellation() {
		CancellationSignal parent = new CancellationSignal();
		CancellationSignal child = new CancellationSignal(parent);
		CancellationSignal grandchild = new CancellationSignal(child);
		assertFalse(child.isCancelled());
		assertFalse(grandchild.isCancelled());

		parent.cancel();

		assertTrue(parent.isCancelled());
		assertTrue(child.isCancelled());
		assertTrue(grandchild.isCancelled());
	}

	@Test
	void childCancellationDoesNotCancelParentOrSibling() {
		CancellationSignal parent = new CancellationSignal();
		CancellationSignal child = new CancellationSignal(parent);
		CancellationSignal sibling = new CancellationSignal(parent);

		child.cancel();

		assertTrue(child.isCancelled());
		assertFalse(parent.isCancelled());
		assertFalse(sibling.isCancelled());
	}

	@Test
	void cancellationIsMonotonicAndFreshRootDoesNotReviveCapturedWork() {
		CancellationSignal oldRoot = new CancellationSignal();
		CancellationSignal oldWork = new CancellationSignal(oldRoot);
		oldRoot.cancel();
		oldRoot.cancel();
		assertTrue(oldRoot.isCancelled());
		assertTrue(oldWork.isCancelled());

		CancellationSignal freshRoot = new CancellationSignal();
		CancellationSignal newWork = new CancellationSignal(freshRoot);
		assertFalse(freshRoot.isCancelled());
		assertFalse(newWork.isCancelled());
		assertTrue(oldWork.isCancelled());

		freshRoot.cancel();
		assertTrue(newWork.isCancelled());
		assertTrue(oldWork.isCancelled());
	}

	@Test
	void deepParentChainPropagatesCancellationWithoutStackOverflow() {
		CancellationSignal root = new CancellationSignal();
		CancellationSignal top = root;
		for (int i = 0; i < 50_000; i++) {
			top = new CancellationSignal(top);
		}

		root.cancel();

		assertTrue(top.isCancelled());
	}

	@Test
	void cachedCombinedViewCannotBePoisonedByOneWorkload() {
		CancellationSignal caller = new CancellationSignal();
		CancellationSignal callee = new CancellationSignal();
		CancellationSignal cached = CancellationSignal.combine(caller, callee);
		CancellationSignal firstWorkload = new CancellationSignal(cached);
		firstWorkload.cancel();
		assertTrue(firstWorkload.isCancelled());
		assertFalse(cached.isCancelled(), "one query must not cancel its cached caller/callee view");
		assertFalse(new CancellationSignal(cached).isCancelled(), "the next workload must remain usable");
		assertThrows(UnsupportedOperationException.class, cached::cancel,
				"a cached combination must expose only the owners' cancellation state");
	}

	@Test
	void nestedCurrentSignalsRestoreAfterExceptionalExit() {
		assertSame(CancellationSignal.NONE, CancellationSignal.current(),
				"the previous test must not leak a current workload signal");
		CancellationSignal outer = new CancellationSignal();
		CancellationSignal previousOuter = CancellationSignal.swapCurrent(outer);
		assertSame(CancellationSignal.NONE, previousOuter);
		RuntimeException failure = new RuntimeException("scope failure");
		try {
			RuntimeException thrown = assertThrows(RuntimeException.class, () -> {
				CancellationSignal inner = new CancellationSignal();
				CancellationSignal previousInner = CancellationSignal.swapCurrent(inner);
				try {
					assertSame(outer, previousInner);
					assertSame(inner, CancellationSignal.current());
					throw failure;
				} finally {
					CancellationSignal.restoreCurrent(previousInner);
				}
			});
			assertSame(failure, thrown);
		} finally {
			CancellationSignal.restoreCurrent(previousOuter);
		}
		assertSame(CancellationSignal.NONE, CancellationSignal.current());
	}
}
